import { expect, test, uniqueName } from "../../fixtures";

test("updating a draft vendor changes its contact email and records an audit event", { tag: "@VEN-08" }, async ({ apiAs }) => {
  // Arrange
  const member = await apiAs("member");
  const created = await member.post("/api/vendors", {
    data: {
      name: uniqueName("Acme Freight"),
      category: "logistics",
      contact_email: `contact-${Date.now().toString(36)}@acme-setup.example`,
    },
  });
  expect(created.status(), await created.text()).toBe(201);
  const vendor = await created.json();
  expect(vendor.status).toBe("draft");

  // Act
  const response = await member.patch(`/api/vendors/${vendor.id}`, {
    data: { contact_email: "billing@acmefreight.example" },
  });

  // Assert
  expect(response.status(), await response.text()).toBe(200);
  const updated = await response.json();
  expect(updated.contact_email).toBe("billing@acmefreight.example");

  await expect
    .poll(
      async () => {
        const audit = await member.get(`/api/vendors/${vendor.id}/audit`);
        expect(audit.status(), await audit.text()).toBe(200);
        const body = (await audit.json()) as { items: { action: string }[] };
        return body.items.map((event) => event.action);
      },
      { message: "audit trail should contain vendor.updated" },
    )
    .toContain("vendor.updated");
});
